class AgentWorkItemResource:
    def __init__(self, http: SyncHttpClient):
        self._http = http

    def list(
        self,
        agent: str,
        *,
        execution: str | None = None,
        limit: int | None = None,
        after_cursor: str | None = None,
    ) -> WorkflowWorkItemList:
        """
        List active workflow work available to the viewer
        Lists queued, claimed, and running external work yielded by durable workflows.
        The top-level collection includes work for every agent the viewer can execute;
        the agent-nested collection limits results to that agent. This discovery
        response never includes lease tokens. Use the agent claim endpoint to acquire
        new work or resume a saved lease.

        Args:
            agent: Agent ID or lookup key injected by the nested route.
            execution: Optional durable execution ID filter.
            limit: Maximum work items per page. Defaults to 50; maximum is 100.
            after_cursor: Opaque cursor for the next page of older queued work.

        Returns:
            Successful response
        """
        query: dict[str, object] = {}
        if execution is not None:
            query["execution"] = execution
        if limit is not None:
            query["limit"] = limit
        if after_cursor is not None:
            query["after_cursor"] = after_cursor
        return self._http.request(
            f"/api/v1/agents/{agent}/work_items",
            query=query,
            response_type=WorkflowWorkItemList,
        )

    def claim(self, agent: str, input: AgentWorkItemClaimInput) -> WorkflowWorkItemClaim:
        """
        Claim or resume workflow work for an agent
        Atomically claims the oldest queued or lease-expired item. To resume after a
        harness restart, pass both the saved `work_item` and the same `lease_owner`;
        the server refreshes that active lease without incrementing its attempt.
        Returns `data: null` when no eligible item exists, including when another
        lease owns the explicitly requested item.

        Args:
            agent: Agent ID or lookup key injected by the nested route.
            input: Request body.
            input.execution: Optional durable execution ID filter.
            input.lease_owner: Caller-generated random UUID lease token.
            input.lease_seconds: Lease duration from 15 through 3600 seconds. Defaults to 300.
            input.work_item: Saved work item ID to resume or reclaim.

        Returns:
            Successful response
        """
        return self._http.request(
            f"/api/v1/agents/{agent}/work_items/claim",
            method="POST",
            body=input,
            response_type=WorkflowWorkItemClaim,
        )


class AgentResource:
    def __init__(self, http: SyncHttpClient):
        self._http = http
        self.agent_computers = AgentAgentComputerResource(http)
        self.agent_env_vars = AgentAgentEnvVarResource(http)
        self.agent_installations = AgentAgentInstallationResource(http)
        self.agent_tools = AgentAgentToolResource(http)
        self.agent_working_memory = AgentWorkingMemoryResource(http)
        self.schedules = ScheduleResource(http)
        self.work_items = AgentWorkItemResource(http)

    def list(
        self,
        *,
        page: int | None = None,
        page_size: int | None = None,
        search: str | None = None,
        user: str | None = None,
        org_id: str | None = None,
        template_config: str | None = None,
        solution_config: builtins.list[str] | None = None,
    ) -> AgentListResponse:
        """
        List agents
        Returns a paginated list of agents visible to the authenticated caller. Results are
        ordered by creation time descending.
        Use `search` to filter by name, org, team, or owner fields. Use `user` or `org_id`
        to scope the list to a specific owner. Use `template_config` to find agents whose
        last applied template matches a given config ID. Use `solution_config` to find
        agents whose last applied template was imported as part of any of the given
        Solution config IDs.
        Pagination is page-based: pass `page` and `page_size` to navigate through large
        result sets. When called under a developer app scope, only agents belonging to that
        app are returned.

        Args:
            page: Page number to retrieve, 1-indexed. Defaults to `1`.
            page_size: Number of agents to return per page. Defaults to `25`.
            search: Free-text search string matched against the agent name, org, team, and owner fields.
            user: User ID (`usr_...`) to filter by. Returns only agents owned by this user.
            org_id: Organization ID (`org_...`) to filter by. Returns only agents owned by this org.
            template_config: Config ID (`cfg_...`) or `lookup_key` of an AgentTemplate. Returns only agents whose last applied template matches.
            solution_config: Solution config IDs (`cfg_...`) to filter by. Returns only agents whose last applied template was imported as part of any of the listed Solutions. Pass one or more IDs.

        Returns:
            Paginated list of agents matching the supplied filters.
        """
        query: dict[str, object] = {}
        if page is not None:
            query["page"] = page
        if page_size is not None:
            query["page_size"] = page_size
        if search is not None:
            query["search"] = search
        if user is not None:
            query["user"] = user
        if org_id is not None:
            query["org_id"] = org_id
        if template_config is not None:
            query["template_config"] = template_config
        if solution_config is not None:
            query["solution_config"] = solution_config
        return self._http.request("/api/v1/agents", query=query, response_type=AgentListResponse)

    def create(self, input: AgentCreateInput) -> AgentCreateResponse:
        """
        Create an agent
        Creates a new agent. Supports two mutually exclusive provisioning modes.
        **Template mode** pass `template` with the ID or `lookup_key` of an existing
        AgentTemplate config. The agent's tools, routines, skills, and installations are
        provisioned from that template's `config_ref` entries.
        **Bundle mode** pass `template_bundle` with a self-contained install payload
        (AgentTemplate body plus every skill, script, and config it references). The entire
        bundle commits in a single transaction; any failure rolls back the whole install and
        the response includes `installed_configs[]` one entry per persisted config.
        Pass exactly one of `template` or `template_bundle`. If neither is supplied, `name`
        is required and a blank agent is created. Requires authentication; when called under
        a developer app scope (`/developer/apps/:app/...`), the caller must hold the app scope
        for the target app.

        Args:
            input: Request body.
            input.acl: Access control list controlling which users, teams, or orgs can read or manage this agent.
            input.description: Human-readable description of what the agent does.
            input.email: Email address assigned to the agent. Used as the agent's contact identity.
            input.identity: System-prompt identity string describing who the agent is. Passed verbatim to the model on each conversation turn.
            input.lookup_key: Stable, unique slug used to look up this agent by name instead of ID. Must be unique within the owning app or org.
            input.metadata: Arbitrary key-value map stored on the agent. Not interpreted by the platform.
            input.model: Default AI model identifier for this agent, e.g. `claude-sonnet-4-5`. Overridden per-request when the caller specifies a model.
            input.name: Display name for the agent. Required when neither `template` nor `template_bundle` is provided.
            input.org: Organization ID (`org_...`) that should own this agent. Mutually exclusive with `team` and `user`.
            input.originator: Free-form label identifying the source or author of the agent, e.g. a user ID, a deploy pipeline, or a slug.
            input.phone_number: Phone number assigned to the agent in E.164 format, e.g. `+15550001234`.
            input.profile_picture: Profile picture to attach to the agent. All three subfields are required when this object is present.
            input.team: Team ID (`team_...`) that should own this agent. Mutually exclusive with `org` and `user`.
            input.template: ID (`cfg_...`) or `lookup_key` of an existing AgentTemplate config to provision from. Mutually exclusive with `template_bundle`.
            input.template_bundle: Self-contained install bundle containing an AgentTemplate plus all referenced skills and configs. The entire bundle is committed atomically. Mutually exclusive with `template`.
            input.user: User ID (`usr_...`) that should own this agent. Mutually exclusive with `org` and `team`.

        Returns:
            The newly created agent. When `template_bundle` was supplied, the response also includes `installed_configs[]` one entry per persisted config object, with `key` echoing the caller-supplied input identifier.
        """
        return self._http.request(
            "/api/v1/agents",
            method="POST",
            body=input,
            response_type=AgentCreateResponse,
        )

    def delete(self, agent: str) -> None:
        """
        Delete an agent
        Permanently deletes an agent and all of its associated resources. This action cannot
        be undone.
        The authenticated caller must own the agent or hold sufficient permissions within its
        owning org or team. When called under a developer app scope, the caller must hold the
        app scope for the target app.

        Args:
            agent: ID (`agi_...`) or `lookup_key` of the agent to delete.

        Returns:
            Empty body. Returns HTTP 204 on success.
        """
        self._http.request(f"/api/v1/agents/{agent}", method="DELETE")

    def get(self, agent: str) -> Agent:
        """
        Retrieve an agent
        Returns the agent identified by ID or `lookup_key`. The authenticated caller must
        own the agent or hold sufficient permissions within its owning org or team.
        When called under a developer app scope, the agent must belong to that app. Use the
        list endpoint to retrieve many agents at once.

        Args:
            agent: ID (`agi_...`) or `lookup_key` of the agent to retrieve.

        Returns:
            The requested agent.
        """
        return self._http.request(f"/api/v1/agents/{agent}", response_type=Agent)

    def update(self, agent: str, input: AgentUpdateInput) -> Agent:
        """
        Update an agent
        Updates one or more fields on an existing agent. Only the fields you supply are
        changed; omitted fields retain their current values.
        To clear the agent's default model, pass `model` as an empty string. The
        authenticated caller must own the agent or hold write permissions within its owning
        org or team. When called under a developer app scope, the caller must hold the app
        scope for the target app.

        Args:
            agent: ID (`agi_...`) or `lookup_key` of the agent to update.
            input: Request body.
            input.acl: Replacement access control list. Fully replaces the existing ACL.
            input.description: New description of what the agent does. Pass an empty string to clear it.
            input.email: New email address for the agent.
            input.identity: Replacement identity system-prompt string describing who the agent is.
            input.lookup_key: New `lookup_key` slug. Must be unique within the owning app or org.
            input.metadata: Replacement key-value metadata map. The entire map is replaced, not merged.
            input.model: New default AI model identifier, e.g. `claude-sonnet-4-5`. Pass an empty string to clear the agent's default model.
            input.name: New display name for the agent.
            input.org: Organization ID (`org_...`) to transfer ownership to.
            input.originator: Replacement originator label identifying the source or author of the agent.
            input.phone_number: New phone number for the agent in E.164 format, e.g. `+15550001234`.
            input.profile_picture: Replacement profile picture. All three subfields are required when this object is present.
            input.team: Team ID (`team_...`) to transfer ownership to.
            input.user: User ID (`usr_...`) to transfer ownership to.

        Returns:
            The updated agent with all current field values.
        """
        return self._http.request(
            f"/api/v1/agents/{agent}",
            method="PATCH",
            body=input,
            response_type=Agent,
        )

    def agent_health_actions(
        self,
        agent: str,
        *,
        source: builtins.list[str] | None = None,
        status: builtins.list[str] | None = None,
        kind: builtins.list[str] | None = None,
    ) -> HealthActionListResponse:
        """
        List health actions for an agent
        Returns all health actions associated with a given agent. Health actions
        represent required or recommended steps such as setting environment
        variables, completing OAuth installations, or running custom verifiers
        that an agent needs to reach a healthy state.
        Results are not paginated; the full list for the agent is returned. Use
        the `source`, `status`, and `kind` filters to narrow results to the
        subset your UI or workflow needs. Multiple values for the same filter
        are treated as OR (e.g. passing two statuses returns actions matching
        either). The caller must be authenticated and scoped to the app that
        owns the agent.

        Args:
            agent: Agent ID (`agt_...`) or lookup key of the agent whose health actions you want to list.
            source: Filter results to actions from one or more lifecycle stages. Accepted values: `"setup"` (actions created during agent installation) and `"health"` (ongoing health checks). Omit to return actions from all stages.
            status: Filter results to actions in one or more statuses. Accepted values: `"pending"`, `"completed"`, `"skipped"`, and `"degraded"`. Omit to return actions in all statuses.
            kind: Filter results to actions of one or more kinds. Accepted values: `"env_var"` (a required secret or config value), `"install"` (an OAuth or integration install step), and `"custom"` (a platform-defined check). Omit to return all kinds.

        Returns:
            Object containing a `data` array of health action objects for the specified agent.
        """
        query: dict[str, object] = {}
        if source is not None:
            query["source"] = source
        if status is not None:
            query["status"] = status
        if kind is not None:
            query["kind"] = kind
        return self._http.request(
            f"/api/v1/agents/{agent}/agent_health_actions",
            query=query,
            response_type=HealthActionListResponse,
        )

    def agent_routines(self, agent: str, input: AgentAgentRoutinesInput) -> AgentRoutine:
        """
        Create a routine
        Creates a new routine and attaches it to the specified agent. Routines define
        how an agent responds to events or a cron schedule; the `handler_type` controls
        which execution model is used.
        The routine is created in `"draft"` status by default. To start processing
        events immediately, either pass `status: "active"` or call the activate
        endpoint after creation. Scheduled routines must run no more frequently than
        once per hour. Requires app scope.

        Args:
            agent: Agent ID (`agt_...`) that this routine will be attached to.
            input: Request body.
            input.acl: Access control list governing who can read or manage this routine.
            input.config: Workflow config ID (`cfg_...`). Required when `handler_type` is `"workflow_graph"`.
            input.description: Optional human-readable description of what this routine does.
            input.event_config: Mapping of event types to trigger configuration. Each key is an event type string; each value is an object with a `"filters"` map and an optional `"dedupe_key_path"` (a JSON path used to deduplicate events, e.g. `"$.thread.id"`).
            input.event_type: Event type that triggers this routine. Deprecated use `event_config` instead.
            input.handler_type: Execution model for this routine. One of `"workflow_graph"`, `"script"`, `"preset"`, or `"chain"`.
            input.lookup_key: Stable, unique key you assign to this routine for deterministic lookup. Must be unique within the app.
            input.message_policy: Visibility and explicit recipient selection for messages emitted by the routine.
            input.metadata: Arbitrary key-value metadata you can attach to the routine. Not interpreted by the platform.
            input.name: Human-readable display name for the routine.
            input.preset_config: Configuration passed to the preset at runtime. Used when `handler_type` is `"preset"`.
            input.preset_name: Name of the registered preset to use. Required when `handler_type` is `"preset"`.
            input.schedule: Cron expression for time-triggered routines (e.g. `"0 9 * * 1"`). Must not be more frequent than once per hour.
            input.script: Inline script source. Required when `handler_type` is `"script"`.
            input.status: Initial lifecycle status. One of `"draft"` or `"active"`. Defaults to `"draft"`.
            input.steps: Ordered list of steps for a chain handler. Required when `handler_type` is `"chain"`; must be omitted or empty otherwise. Each step must have exactly one handler body field (`preset_name`, `script`, or `config`) matching that step's `handler_type`.
            input.trigger_context: Context in which the routine is triggered. One of `"chat_session"` or `"event"`. Defaults to `"event"`.
            input.user: Optional co-owner user ID (`usr_...`). When set, that user shares authority over this routine (view/modify/delete) without needing to administer the parent agent. Must be supplied explicitly the caller's identity is never auto-stamped as co-owner.

        Returns:
            The newly created routine.
        """
        return self._http.request(
            f"/api/v1/agents/{agent}/agent_routines",
            method="POST",
            body=input,
            response_type=AgentRoutine,
        )

    def export(self, agent: str, *, remove_identity: bool | None = None) -> AgentExport:
        """
        Export an agent as an AgentTemplate
        Reconstructs an AgentTemplate config from a deployed agent and all of its
        sub-resources (tools, routines, skills, installations). Returns the template
        definition together with every dependent config file (scripts, workflows, skills,
        schemas) and their raw content, producing a fully self-contained export bundle.
        Use this endpoint to snapshot an agent's current configuration for backup,
        migration, or to seed a new Solution template. Pass `remove_identity: true` to
        strip instance-specific fields (email, phone number) before export.
        The authenticated caller must own the agent or hold sufficient permissions within
        its owning org or team. When called under a developer app scope, the caller must
        hold the app scope for the target app.

        Args:
            agent: ID (`agi_...`) or `lookup_key` of the agent to export.
            remove_identity: When `true`, strips instance-unique identity fields (`email`, `phone_number`) from the exported template so it can be reused as a generic blueprint.

        Returns:
            Export bundle containing the reconstructed AgentTemplate and all dependent config files with their raw content.
        """
        query: dict[str, object] = {}
        if remove_identity is not None:
            query["remove_identity"] = remove_identity
        return self._http.request(
            f"/api/v1/agents/{agent}/export",
            query=query,
            response_type=AgentExport,
        )

    def health(self, agent: str) -> AgentHealth:
        """
        Retrieve an agent's health profile
        Returns an aggregate health profile for the specified agent, including an overall
        status, a numeric health score, recent activity metrics, and a list of recommended
        remediation actions.
        The health check is computed on demand at request time. The `checked_at` timestamp
        in the response reflects when the evaluation ran. Use this endpoint to surface
        diagnostics about tool availability, model configuration, and runtime activity in
        dashboards or monitoring workflows.
        The authenticated caller must own the agent or hold sufficient permissions within
        its owning org or team. When called under a developer app scope, the caller must
        hold the app scope for the target app.

        Args:
            agent: ID (`agi_...`) or `lookup_key` of the agent to evaluate.

        Returns:
            Aggregate health profile for the agent, including status, score, activity metrics, and recommended actions.
        """
        return self._http.request(f"/api/v1/agents/{agent}/health", response_type=AgentHealth)

    def search(self, agent: str, input: AgentSearchInput) -> AgentSearchResponse:
        """
        Search an agent's knowledge base
        Performs a semantic search over an agent's knowledge base and returns a ranked,
        `kind`-discriminated list of matching items.
        Two item kinds may appear in `data`:
        - `"chunk"` chunk-level results from the agent's context store. Present for all agents.
        - `"document"` document-level results. Present only when the agent has an active
        `archastro/knowledge` installation.
        Results from both kinds are scored with Reciprocal Rank Fusion (RRF), normalized to
        be comparable across kinds, then merged into a single ranked list. On a relevance tie,
        chunks appear before documents. The total number of results is capped at `max_results`
        across both kinds.
        Use `mode` to choose the retrieval strategy: `"hybrid"` (default) combines vector and
        full-text search; `"vector"` and `"fulltext"` select each strategy independently.

        Args:
            agent: ID (`agi_...`) or `lookup_key` of the agent whose knowledge base to search.
            input: Request body.
            input.max_results: Maximum total results to return across all kinds. Chunks and documents are ranked together and the list is capped at this value. Defaults to `20`; maximum is `100`.
            input.min_similarity: Cosine-similarity floor for the vector leg, 0.0-1.0, applied to both chunk and document results. Candidates below it are discarded before ranking, so a high value trades recall for precision. Pass `0.0` to disable the floor when a missed match costs more than a weak one note that with no floor every query returns results, so an empty response can no longer be read as "no match". Omit to use the default.
            input.mode: Retrieval strategy. One of `"hybrid"` (default), `"vector"`, or `"fulltext"`.
            input.query: Natural-language search query used to retrieve relevant knowledge items.
            input.recency_days: When set, restricts results to items indexed within the last N days.
            input.source_types: Array of source-type slugs used to filter chunk results, e.g. `["web", "file"]`. Omit to include all source types.

        Returns:
            Successful response
        """
        return self._http.request(
            f"/api/v1/agents/{agent}/search",
            method="POST",
            body=input,
            response_type=AgentSearchResponse,
        )

    def threads(self, agent: str, input: AgentThreadsInput) -> Thread:
        """
        Create a thread for an agent
        Creates a new thread owned by the specified agent. The thread is scoped to the
        agent's identity and is immediately available for messaging.
        The authenticated caller must have access to the agent's parent app. If your
        API key is scoped to a specific app, pass that app's ID via the `app` parameter.
        Attempting to create a thread for an agent you cannot access returns 404.
        By default the platform may send an automatic welcome message into the new
        thread. Pass `skip_welcome_message: true` to suppress this behavior.

        Args:
            agent: Agent ID (`agt_...`). The thread will be owned by this agent.
            input: Request body.
            input.skip_welcome_message: When `true`, suppresses the automatic welcome message that the platform sends when a new thread is created. Defaults to `false`.
            input.thread: Attributes for the new thread. See ThreadCreateParams for available fields.

        Returns:
            The newly created thread.
        """
        return self._http.request(
            f"/api/v1/agents/{agent}/threads",
            method="POST",
            body=input,
            response_type=Thread,
        )

    def upgrade(self, agent: str, input: AgentUpgradeInput) -> AgentUpgradeResponse:
        """
        Upgrade an agent from an AgentTemplate
        Upgrades an existing agent by reconciling it against an AgentTemplate from a
        Solution. Supports two modes:
        - `"reapply"` (default) re-applies the agent's currently tracked template,
        picking up any changes the template author has made since the last apply.
        - `"replace"` moves the agent to a different template. `template` is required
        in this mode.
        Set `dry_run: true` to compute and return the full upgrade diff (adds, updates,
        removes, noops) without writing any changes. The response includes a
        `review_fingerprint` you can pass back via `expected_review_fingerprint` on the
        live apply to guard against the diff changing between review and execution.
        Safe overrides (`name`, `description`, `email`, `phone_number`, `metadata`,
        `identity`, `originator`, `model`) let you pin instance-specific values that
        should not be overwritten by the template during the upgrade.
        The authenticated caller must own the agent or hold write permissions within its
        owning org or team. When called under a developer app scope, the caller must hold
        the app scope for the target app.

        Args:
            agent: ID (`agi_...`) or `lookup_key` of the agent to upgrade.
            input: Request body.
            input.description: Instance-specific description override. Pins this value so the template upgrade does not overwrite it.
            input.dry_run: When `true`, computes and returns the full upgrade diff without persisting any changes. Use with `expected_review_fingerprint` to guard the live apply.
            input.email: Instance-specific email address override. Pins this value so the template upgrade does not overwrite it.
            input.expected_review_fingerprint: Stale-review guard. Pass the `review_fingerprint` returned by a prior `dry_run` response to ensure the diff has not changed between review and live apply. Returns an error if the fingerprint no longer matches.
            input.identity: Instance-specific identity system-prompt override. Pins this value so the template upgrade does not overwrite it.
            input.metadata: Instance-specific metadata override. Pins this value so the template upgrade does not overwrite it.
            input.mode: Upgrade mode. `"reapply"` (default) refreshes the agent's tracked template; `"replace"` moves the agent to a different template (requires `template`).
            input.model: Instance-specific default model override. Pins this value so the template upgrade does not overwrite it. Pass an empty string to clear the model.
            input.name: Instance-specific name override. Pins this value so the template upgrade does not overwrite it.
            input.originator: Instance-specific originator label override. Pins this value so the template upgrade does not overwrite it.
            input.phone_number: Instance-specific phone number override in E.164 format. Pins this value so the template upgrade does not overwrite it.
            input.template: ID (`cfg_...`) or `lookup_key` of the target AgentTemplate config. Optional in `"reapply"` mode; required in `"replace"` mode.

        Returns:
            The upgrade outcome, including the updated agent, the source Solution and template summaries, and the full diff (`upgrade_result`) with status, dry-run flag, aggregate counts, and a per-resource change list. When `dry_run` is `true`, `agent` is `null` and no changes are persisted.
        """
        return self._http.request(
            f"/api/v1/agents/{agent}/upgrade",
            method="POST",
            body=input,
            response_type=AgentUpgradeResponse,
        )
